llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Valdecoxib, a primary arylsulfonamide, has an absolute oral bioavailability of 83% versus IV in humans, directly supporting high F for the sulfonamide-bearing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Ziprasidone, a chloro-substituted heteroaromatic drug, has an absolute oral bioavailability of 60% under fed conditions, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Sildenafil, a sulfonamide-containing heteroaromatic drug, has an adult absolute oral bioavailability of 38% versus IV, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Fasudil, an isoquinoline sulfonamide, has an absolute oral bioavailability of 69% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "d-Fenfluramine, a chloro-substituted aromatic amine, has an oral bioavailability of 61-69%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to high oral bioavailability: sulfonamide-containing analogues (valdecoxib 83%, fasudil 69%, sildenafil 38-41%) and chloro/heteroaromatic drugs (ziprasidone 60%, d-fenfluramine 61-69%) exceed the 20% threshold. Chlorothiazide is therefore predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct chlorothiazide oral bioavailability measurement is present in the supplied evidence; prediction relies on transferable analogues.",
    "The only sub-20% F value (sildenafil in premature infants, 2.78%) is from a special population and enteral route, so it is not transferable to adult oral dosing.",
    "Food effects and formulation can shift F, but all adult analogue values remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

